window.DUAS_DATA={"duas": [{"id": 1, "title": "ہدایت، تقویٰ، پاک دامنی اور بے نیازی کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى", "urdu": "اے اللہ! میں تجھ سے ہدایت، تقویٰ، پاک دامنی اور (لوگوں سے) بے نیازی مانگتا ہوں۔", "ref": "صحیح مسلم 2721", "cats": ["other"]}, {"id": 2, "title": "دین، دنیا اور آخرت سنورنے کی جامع دعا", "arabic": "اللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ", "urdu": "اے اللہ! میرا دین درست فرما دے جو میرے ہر کام کی حفاظت ہے، میری دنیا درست فرما دے جس میں میری روزی ہے، اور میری آخرت درست فرما دے جہاں مجھے لوٹ کر جانا ہے۔ زندگی کو میرے لیے ہر نیکی میں اضافے کا ذریعہ بنا دے اور موت کو ہر برائی سے میرے لیے راحت بنا دے۔", "ref": "صحیح مسلم 2720", "cats": ["other"]}, {"id": 3, "title": "دلوں کو اطاعت کی طرف پھیرنے کی دعا", "arabic": "اللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ", "urdu": "اے دلوں کو پھیرنے والے اللہ! ہمارے دلوں کو اپنی فرماں برداری کی طرف پھیر دے۔", "ref": "صحیح مسلم 2654", "cats": ["other"]}, {"id": 4, "title": "دین پر ثابت قدمی کی دعا", "arabic": "يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ", "urdu": "اے دلوں کو پلٹنے والے! میرے دل کو اپنے دین پر ثابت رکھ۔", "ref": "سنن ترمذی 2140", "cats": ["other"]}, {"id": 5, "title": "ہر قسم کی خطا کی معافی کی دعا", "arabic": "اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي جِدِّي وَهَزْلِي، وَخَطَئِي وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي، اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "urdu": "اے اللہ! میری خطا، میری نادانی، اپنے کاموں میں میری زیادتی اور وہ سب کچھ بخش دے جسے تو مجھ سے زیادہ جانتا ہے۔ اے اللہ! میری سنجیدگی اور مذاق، میری غلطی اور جان بوجھ کر کیا ہوا گناہ بخش دے، یہ سب میرے ہی اندر ہیں۔ اے اللہ! میرے اگلے اور پچھلے، چھپے اور ظاہر گناہ بخش دے۔ تو ہی آگے کرنے والا ہے، تو ہی پیچھے کرنے والا ہے اور تو ہر چیز پر قادر ہے۔", "ref": "صحیح بخاری 6398، صحیح مسلم 2719", "cats": ["istighfar"]}, {"id": 6, "title": "نعمت کے زوال اور اچانک پکڑ سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ", "urdu": "اے اللہ! میں تیری نعمت کے ختم ہونے، تیری دی ہوئی عافیت کے پلٹ جانے، تیری اچانک پکڑ اور تیری ہر ناراضی سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح مسلم 2739", "cats": ["other"]}, {"id": 7, "title": "بے فائدہ علم، سخت دل اور نامقبول دعا سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا", "urdu": "اے اللہ! میں اس علم سے جو فائدہ نہ دے، اس دل سے جو (تجھ سے) نہ ڈرے، اس نفس سے جو کبھی سیر نہ ہو اور اس دعا سے جو قبول نہ ہو، تیری پناہ مانگتا ہوں۔", "ref": "صحیح مسلم 2722", "cats": ["other"]}, {"id": 8, "title": "اللہ کے خوف، یقین اور دینی سلامتی کی جامع دعا", "arabic": "اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا", "urdu": "اے اللہ! ہمیں اپنا اتنا خوف عطا فرما جو ہمارے اور ہمارے گناہوں کے درمیان رکاوٹ بن جائے، اتنی فرماں برداری دے جو ہمیں تیری جنت تک پہنچا دے، اور ایسا یقین دے جس سے دنیا کی مصیبتیں ہم پر آسان ہو جائیں۔ جب تک زندہ رکھے ہمیں کان، آنکھوں اور طاقت سے فائدہ دیتا رہ، اور انہیں آخر تک ہمارے ساتھ باقی رکھ۔ جس نے ہم پر ظلم کیا اس سے بدلہ (انصاف کے ساتھ) دلا، ہمارے دشمنوں کے مقابلے میں ہماری مدد فرما، ہماری مصیبت ہمارے دین میں نہ ڈال، دنیا کو ہماری سب سے بڑی فکر اور ہمارے علم کی انتہا نہ بنا، اور ہم پر ایسے شخص کو مسلط نہ کر جو ہم پر رحم نہ کرے۔", "ref": "سنن ترمذی 3502", "cats": ["other"]}, {"id": 9, "title": "نور کی دعا", "arabic": "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ مِنْ خَلْفِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَاجْعَلْ مِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، اللَّهُمَّ أَعْطِنِي نُورًا", "urdu": "اے اللہ! میرے دل میں نور رکھ دے، میری زبان میں نور، میرے کانوں میں نور اور میری آنکھوں میں نور رکھ دے۔ میرے پیچھے اور میرے آگے نور کر دے، میرے اوپر اور میرے نیچے نور کر دے۔ اے اللہ! مجھے (کامل) نور عطا فرما۔", "ref": "صحیح مسلم 763 (اصل واقعہ: صحیح بخاری 6316)", "cats": ["other"]}, {"id": 10, "title": "حسنِ اخلاق کی دعا", "arabic": "اللَّهُمَّ كَمَا حَسَّنْتَ خَلْقِي فَحَسِّنْ خُلُقِي", "urdu": "اے اللہ! جس طرح تو نے میری صورت اچھی بنائی ہے، اسی طرح میرے اخلاق بھی اچھے بنا دے۔", "ref": "مسند احمد 3823؛ ارواء الغلیل 74 (صحیح)", "cats": ["other"]}, {"id": 11, "title": "بہترین اخلاق کی ہدایت اور بُرے اخلاق سے حفاظت", "arabic": "وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ", "urdu": "اور مجھے سب سے اچھے اخلاق کی ہدایت دے، تیرے سوا کوئی اچھے اخلاق کی ہدایت نہیں دے سکتا۔ اور مجھ سے بُرے اخلاق دور کر دے، تیرے سوا کوئی بُرے اخلاق دور نہیں کر سکتا۔", "ref": "صحیح مسلم 771 (نماز کی ابتدائی دعا کا حصہ)", "cats": ["other"]}, {"id": 12, "title": "اسمِ اعظم کے وسیلے سے دعا (توحید کے ساتھ)", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ، الْأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ", "urdu": "اے اللہ! میں تجھ سے مانگتا ہوں اس گواہی کے ساتھ کہ تو ہی اللہ ہے، تیرے سوا کوئی معبود نہیں، تو اکیلا اور بے نیاز ہے، نہ اس کی کوئی اولاد ہے نہ وہ کسی کی اولاد ہے، اور کوئی اس کے برابر نہیں۔", "ref": "سنن ابو داود 1493، سنن ترمذی 3475، سنن ابن ماجہ 3857", "cats": ["other"]}, {"id": 13, "title": "اسمِ اعظم کے ساتھ حمد و ثنا والی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ، لَا إِلَهَ إِلَّا أَنْتَ، وَحْدَكَ لَا شَرِيكَ لَكَ، الْمَنَّانُ، يَا بَدِيعَ السَّمَاوَاتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ، إِنِّي أَسْأَلُكَ", "urdu": "اے اللہ! میں تجھ سے مانگتا ہوں کیونکہ ہر تعریف تیرے ہی لیے ہے، تیرے سوا کوئی معبود نہیں، تو اکیلا ہے، تیرا کوئی شریک نہیں، تو بہت احسان کرنے والا ہے، آسمانوں اور زمین کو بغیر نمونے کے بنانے والا، عظمت اور بزرگی والا، زندہ اور سب کو سنبھالنے والا ہے۔ (پھر اپنی حاجت مانگے۔)", "ref": "سنن ابو داود 1495، سنن ترمذی 3544، سنن نسائی 1300، سنن ابن ماجہ 3858", "cats": ["other"]}, {"id": 14, "title": "پریشانی اور بے چینی کی دعا", "arabic": "اللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ", "urdu": "اے اللہ! میں تیری رحمت کی امید رکھتا ہوں، پس مجھے پلک جھپکنے کے برابر بھی میرے نفس کے حوالے نہ کر، میرے سارے کام سنوار دے، تیرے سوا کوئی معبود نہیں۔", "ref": "سنن ابو داود 5090", "cats": ["morning", "evening", "distress"]}, {"id": 15, "title": "بھوک اور خیانت سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ", "urdu": "اے اللہ! میں بھوک سے تیری پناہ مانگتا ہوں کیونکہ وہ بہت بُرا ساتھی ہے، اور خیانت سے تیری پناہ مانگتا ہوں کیونکہ وہ بہت بُرا رازدار ہے۔", "ref": "سنن ابو داود 1547، سنن نسائی 5468، سنن ابن ماجہ 3354", "cats": ["distress"]}, {"id": 16, "title": "جھگڑے، نفاق اور بداخلاقی سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشِّقَاقِ وَالنِّفَاقِ وَسُوءِ الْأَخْلَاقِ", "urdu": "اے اللہ! میں تجھ سے باہمی جھگڑے، نفاق اور بُرے اخلاق سے پناہ مانگتا ہوں۔", "ref": "سنن ابو داود 1546، سنن نسائی 5486", "cats": ["other"]}, {"id": 17, "title": "نفع بخش علم، پاکیزہ رزق اور مقبول عمل کی دعا (فجر کے بعد)", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا", "urdu": "اے اللہ! میں تجھ سے نفع دینے والا علم، پاکیزہ (حلال) رزق اور قبول ہونے والا عمل مانگتا ہوں۔", "ref": "سنن ابن ماجہ 925", "cats": ["morning"]}, {"id": 18, "title": "علم میں نفع اور اضافے کی دعا", "arabic": "اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا", "urdu": "اے اللہ! جو تو نے مجھے سکھایا اس سے مجھے نفع دے، مجھے وہ سکھا جو میرے لیے فائدہ مند ہو، اور میرے علم میں اضافہ فرما۔", "ref": "سنن ترمذی 3599، سنن ابن ماجہ 251", "cats": ["daily"]}, {"id": 19, "title": "حلال رزق اور قرض سے نجات کی دعا", "arabic": "اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ", "urdu": "اے اللہ! مجھے حلال دے کر حرام سے بچا لے، اور اپنے فضل سے اپنے سوا سب سے بے نیاز کر دے۔", "ref": "سنن ترمذی 3563", "cats": ["distress"]}, {"id": 20, "title": "مشکل کام آسان ہونے کی دعا", "arabic": "اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا", "urdu": "اے اللہ! آسان وہی ہے جسے تو آسان کر دے، اور تو چاہے تو مشکل کو بھی آسان بنا دیتا ہے۔", "ref": "صحیح ابن حبان 974", "cats": ["distress"]}, {"id": 21, "title": "نیکیوں کی توفیق اور اللہ کی محبت کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ، وَتَرْكَ الْمُنْكَرَاتِ، وَحُبَّ الْمَسَاكِينِ، وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي، وَإِذَا أَرَدْتَ فِتْنَةً فِي قَوْمٍ فَتَوَفَّنِي غَيْرَ مَفْتُونٍ، وَأَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَحُبَّ عَمَلٍ يُقَرِّبُ إِلَى حُبِّكَ", "urdu": "اے اللہ! میں تجھ سے نیک کام کرنے، برے کام چھوڑنے اور مسکینوں سے محبت کی توفیق مانگتا ہوں، اور یہ کہ تو مجھے بخش دے اور مجھ پر رحم فرما۔ جب تو کسی قوم کو آزمائش میں ڈالنا چاہے تو مجھے آزمائش میں پڑے بغیر اٹھا لینا۔ میں تجھ سے تیری محبت، تجھ سے محبت کرنے والوں کی محبت، اور ایسے عمل کی محبت مانگتا ہوں جو مجھے تیری محبت کے قریب کر دے۔", "ref": "سنن ترمذی 3235", "cats": ["other"]}, {"id": 22, "title": "جان بوجھ کر اور انجانے میں شرک سے حفاظت", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ", "urdu": "اے اللہ! میں اس بات سے تیری پناہ مانگتا ہوں کہ جانتے ہوئے تیرے ساتھ شرک کروں، اور جس (شرک) کو میں نہیں جانتا اس کی تجھ سے معافی مانگتا ہوں۔", "ref": "الادب المفرد 716؛ مسند احمد (صحیح)", "cats": ["other"]}, {"id": 23, "title": "بُرے اخلاق، اعمال اور خواہشات سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ", "urdu": "اے اللہ! میں بُرے اخلاق، بُرے اعمال اور بُری خواہشات سے تیری پناہ مانگتا ہوں۔", "ref": "سنن ترمذی 3591", "cats": ["other"]}, {"id": 24, "title": "برص، جنون، جذام اور بُری بیماریوں سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبَرَصِ وَالْجُنُونِ وَالْجُذَامِ وَمِنْ سَيِّئِ الْأَسْقَامِ", "urdu": "اے اللہ! میں برص، پاگل پن، کوڑھ اور بُری بیماریوں سے تیری پناہ مانگتا ہوں۔", "ref": "سنن ابو داود 1554، سنن نسائی 5493", "cats": ["illness"]}, {"id": 25, "title": "جسم، سماعت اور بصارت کی عافیت کی دعا", "arabic": "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ", "urdu": "اے اللہ! میرے بدن کو عافیت دے، میرے کانوں کو عافیت دے، میری آنکھوں کو عافیت دے، تیرے سوا کوئی معبود نہیں۔", "ref": "سنن ابو داود، کتاب الادب، باب ما یقول اذا اصبح (حدیث ابو بکرہ رضی اللہ عنہ)", "cats": ["morning", "evening", "illness"]}, {"id": 26, "title": "دین، دنیا، گھر اور مال کی عافیت، اور پردہ پوشی کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي", "urdu": "اے اللہ! میں تجھ سے اپنے دین، دنیا، گھر والوں اور مال میں معافی اور عافیت مانگتا ہوں۔ اے اللہ! میرے عیبوں پر پردہ ڈال دے اور میری گھبراہٹوں کو امن میں بدل دے۔", "ref": "سنن ابو داود 5074، سنن ابن ماجہ 3871", "cats": ["morning", "evening"]}, {"id": 27, "title": "زندگی اور موت میں بہتر فیصلے کی دعا", "arabic": "اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ، أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي", "urdu": "اے اللہ! اپنے علمِ غیب اور مخلوق پر اپنی قدرت کے واسطے سے، مجھے اس وقت تک زندہ رکھ جب تک زندگی میرے لیے بہتر ہو، اور مجھے اس وقت وفات دے جب موت میرے لیے بہتر ہو۔", "ref": "سنن نسائی 1305؛ مسند احمد (صحیح)", "cats": ["other"]}, {"id": 28, "title": "دین کے کام میں ثابت قدمی اور شکر کی توفیق", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَحُسْنَ عِبَادَتِكَ", "urdu": "اے اللہ! میں تجھ سے (دین کے) کام میں ثابت قدمی اور ہدایت کے راستے پر پختہ ارادہ مانگتا ہوں، اور تیری نعمت کا شکر اور اچھے طریقے سے تیری عبادت کی توفیق مانگتا ہوں۔", "ref": "مسند احمد؛ السلسلہ الصحیحہ (البانی: صحیح)", "cats": ["other"]}, {"id": 29, "title": "ذکر، شکر اور اچھی عبادت میں مدد کی دعا", "arabic": "اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ", "urdu": "اے اللہ! اپنے ذکر، اپنے شکر اور اچھے انداز میں اپنی عبادت کرنے میں میری مدد فرما۔", "ref": "سنن ابو داود 1522، سنن نسائی 1303", "cats": ["other"]}, {"id": 30, "title": "اختلاف کے وقت حق کی طرف رہنمائی کی دعا", "arabic": "اللَّهُمَّ رَبَّ جِبْرَائِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ", "urdu": "اے اللہ! جبرائیل، میکائیل اور اسرافیل کے رب، آسمانوں اور زمین کے پیدا کرنے والے، غیب و ظاہر کے جاننے والے! تو ہی اپنے بندوں کے درمیان ان باتوں کا فیصلہ کرے گا جن میں وہ اختلاف کرتے ہیں۔ جن باتوں میں اختلاف ہوا ان میں اپنے حکم سے مجھے حق کی راہ دکھا دے، بے شک تو جسے چاہے سیدھے راستے کی ہدایت دیتا ہے۔", "ref": "صحیح مسلم 770", "cats": ["other"]}, {"id": 31, "title": "دونوں سجدوں کے درمیان کی دعا", "arabic": "رَبِّ اغْفِرْ لِي وَارْحَمْنِي وَاجْبُرْنِي وَارْفَعْنِي وَارْزُقْنِي وَاهْدِنِي", "urdu": "اے میرے رب! مجھے بخش دے، مجھ پر رحم فرما، میری کمی پوری فرما دے، مجھے بلند مرتبہ دے، مجھے رزق عطا کر اور مجھے ہدایت دے۔", "ref": "سنن ابو داود 850، سنن ترمذی 284", "cats": ["salah"]}, {"id": 32, "title": "رکوع و سجدے میں فرشتوں اور جبریل کے رب کی پاکی", "arabic": "سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ", "urdu": "(اللہ) نہایت پاک اور نہایت مقدس ہے، فرشتوں اور جبریل کا رب ہے۔", "ref": "صحیح مسلم 487", "cats": ["salah"]}, {"id": 33, "title": "رکوع و سجدے میں تسبیح کے ساتھ مغفرت کی دعا", "arabic": "سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي", "urdu": "اے اللہ! اے ہمارے رب! تو پاک ہے اور اپنی تعریف کے ساتھ ہے، اے اللہ! مجھے بخش دے۔", "ref": "صحیح بخاری 817، صحیح مسلم 484", "cats": ["salah"]}, {"id": 34, "title": "سجدے میں اللہ کی رضا کے وسیلے سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ", "urdu": "اے اللہ! میں تیری رضا کے ذریعے تیری ناراضی سے، تیری معافی کے ذریعے تیری سزا سے، اور خود تجھ ہی سے تیری پناہ مانگتا ہوں۔ میں تیری تعریف شمار نہیں کر سکتا، تو ویسا ہی ہے جیسی تو نے خود اپنی تعریف کی۔", "ref": "صحیح مسلم 486", "cats": ["salah"]}, {"id": 35, "title": "گناہوں سے مکمل پاکی کی دعا", "arabic": "اللَّهُمَّ اغْسِلْ خَطَايَايَ بِمَاءِ الثَّلْجِ وَالْبَرَدِ، وَنَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ", "urdu": "اے اللہ! میرے گناہ برف اور اولے کے پانی سے دھو دے، میرے دل کو گناہوں سے ایسے صاف کر دے جیسے سفید کپڑا میل سے صاف کیا جاتا ہے، اور مجھ میں اور میرے گناہوں میں اتنی دوری کر دے جتنی مشرق اور مغرب میں ہے۔", "ref": "صحیح بخاری 744، صحیح مسلم 598", "cats": ["salah", "istighfar"]}, {"id": 36, "title": "تہجد کی جامع دعا (حمد، ایمان اور توکل)", "arabic": "اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ قَيِّمُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، أَنْتَ نُورُ السَّمَاوَاتِ وَالْأَرْضِ، وَلَكَ الْحَمْدُ، أَنْتَ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَلِقَاؤُكَ حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالسَّاعَةُ حَقٌّ، اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ إِلَهِي لَا إِلَهَ إِلَّا أَنْتَ", "urdu": "اے اللہ! سب تعریف تیرے ہی لیے ہے، تو آسمانوں اور زمین کو اور ان میں موجود سب کو قائم رکھنے والا ہے، تو ان کا نور ہے اور ان کا رب ہے۔ تو حق ہے، تیرا وعدہ حق ہے، تجھ سے ملاقات حق ہے، تیرا فرمان حق ہے، جنت حق ہے، جہنم حق ہے اور قیامت حق ہے۔ اے اللہ! میں تیرا فرماں بردار ہوا، تجھ پر ایمان لایا، تجھ پر بھروسا کیا، تیری طرف رجوع کیا، تیری مدد سے (دشمنوں سے) جھگڑا کیا اور تیرے ہی پاس فیصلہ لایا۔ پس میرے اگلے پچھلے اور چھپے ظاہر گناہ بخش دے، تو ہی میرا معبود ہے، تیرے سوا کوئی معبود نہیں۔", "ref": "صحیح بخاری 1120 (اور صحیح مسلم 769)", "cats": ["salah"]}, {"id": 37, "title": "تشہد کے بعد جنت مانگنے اور جہنم سے پناہ کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ", "urdu": "اے اللہ! میں تجھ سے جنت مانگتا ہوں اور جہنم سے تیری پناہ چاہتا ہوں۔", "ref": "سنن ابو داود 792", "cats": ["salah"]}, {"id": 38, "title": "جنت اور اس کے قریب کرنے والے اعمال کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ", "urdu": "اے اللہ! میں تجھ سے جنت مانگتا ہوں اور ہر اس قول و عمل کی توفیق جو جنت کے قریب کرے، اور جہنم سے اور ہر اس قول و عمل سے تیری پناہ مانگتا ہوں جو جہنم کے قریب کرے۔", "ref": "سنن ابن ماجہ 3846 (ایک طویل دعا کا حصہ)", "cats": ["salah"]}, {"id": 39, "title": "مسجد سے نکلتے وقت اللہ کے فضل کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ", "urdu": "اے اللہ! میں تجھ سے تیرا فضل مانگتا ہوں۔", "ref": "صحیح مسلم 713", "cats": ["daily"]}, {"id": 40, "title": "گھر سے نکلتے وقت توکل کی دعا", "arabic": "بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "urdu": "اللہ کے نام سے، میں نے اللہ پر بھروسا کیا، اور گناہ سے بچنے کی طاقت اور نیکی کی قوت صرف اللہ کی مدد سے ہے۔", "ref": "سنن ابو داود 5095، سنن ترمذی 3426", "cats": ["daily"]}, {"id": 41, "title": "گمراہی، لغزش، ظلم اور جہالت سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ", "urdu": "اے اللہ! میں تیری پناہ مانگتا ہوں اس سے کہ میں خود گمراہ ہوں یا کوئی مجھے گمراہ کرے، میں پھسلوں یا مجھے پھسلایا جائے، میں ظلم کروں یا مجھ پر ظلم ہو، میں جہالت کروں یا مجھ سے جہالت برتی جائے۔", "ref": "سنن ابو داود 5094، سنن ترمذی 3427، سنن ابن ماجہ 3884", "cats": ["magic_shaitan"]}, {"id": 42, "title": "سونے سے پہلے قرض ادا ہونے اور محتاجی دور ہونے کی دعا", "arabic": "اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ", "urdu": "اے اللہ! سات آسمانوں اور عرشِ عظیم کے رب، ہمارے اور ہر چیز کے رب، دانے اور گٹھلی کو پھاڑنے والے، تورات، انجیل اور قرآن اتارنے والے! میں ہر اس چیز کے شر سے تیری پناہ مانگتا ہوں جس کی پیشانی تیرے قبضے میں ہے۔ اے اللہ! تو ہی سب سے پہلے ہے، تجھ سے پہلے کچھ نہیں؛ تو ہی سب کے بعد ہے، تیرے بعد کچھ نہیں؛ تو ہی سب سے اوپر ہے، تجھ سے اوپر کچھ نہیں؛ تو ہی سب سے قریب ہے، تجھ سے قریب کچھ نہیں۔ ہمارا قرض ادا کروا دے اور ہمیں محتاجی سے بے نیاز کر دے۔", "ref": "صحیح مسلم 2713", "cats": ["sleep", "distress"]}, {"id": 43, "title": "ناگہانی اور بُری موتوں سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ التَّرَدِّي وَالْهَدْمِ وَالْغَرَقِ وَالْحَرِيقِ، وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا", "urdu": "اے اللہ! میں بلندی سے گرنے، دیوار وغیرہ کے نیچے دبنے، ڈوبنے اور جلنے سے تیری پناہ مانگتا ہوں۔ موت کے وقت شیطان کے مجھے بہکانے سے، تیری راہ میں پیٹھ پھیر کر مرنے سے، اور زہریلے ڈنک سے مرنے سے بھی تیری پناہ مانگتا ہوں۔", "ref": "سنن ابو داود 1552، سنن نسائی 5531", "cats": ["magic_shaitan"]}, {"id": 44, "title": "وضو کے بعد توبہ کرنے والوں اور پاک رہنے والوں میں شمولیت کی دعا", "arabic": "اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ", "urdu": "اے اللہ! مجھے بہت توبہ کرنے والوں میں شامل فرما اور مجھے خوب پاک رہنے والوں میں شامل فرما۔", "ref": "سنن ترمذی 55", "cats": ["salah"]}, {"id": 45, "title": "وضو کے بعد توبہ و استغفار کی دعا", "arabic": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ", "urdu": "اے اللہ! تو پاک ہے اور اپنی تعریف کے ساتھ ہے، میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں، میں تجھ سے بخشش مانگتا ہوں اور تیری طرف توبہ کرتا ہوں۔", "ref": "عمل الیوم واللیلۃ للنسائی 81؛ ارواء الغلیل 969 (صحیح)", "cats": ["salah", "istighfar"]}, {"id": 46, "title": "میزبان کے لیے برکت و مغفرت کی دعا", "arabic": "اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ", "urdu": "اے اللہ! جو رزق تو نے ان کو دیا اس میں برکت دے، ان کو بخش دے اور ان پر رحم فرما۔", "ref": "صحیح مسلم 2042", "cats": ["daily"]}, {"id": 47, "title": "روزہ افطار کروانے والے کے لیے دعا", "arabic": "أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ", "urdu": "تمہارے ہاں روزہ دار افطار کرتے رہیں، نیک لوگ تمہارا کھانا کھاتے رہیں، اور فرشتے تمہارے لیے رحمت کی دعا کرتے رہیں۔", "ref": "سنن ابو داود 3854، سنن ابن ماجہ 1747", "cats": ["other"]}, {"id": 48, "title": "افطار کے وقت کی دعا", "arabic": "ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ", "urdu": "پیاس چلی گئی، رگیں تر ہو گئیں اور ان شاء اللہ اجر پکا ہو گیا۔", "ref": "سنن ابو داود 2357", "cats": ["other"]}, {"id": 49, "title": "کھلانے پلانے والے کے لیے دعا", "arabic": "اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي", "urdu": "اے اللہ! جس نے مجھے کھلایا اسے کھلا، اور جس نے مجھے پلایا اسے پلا۔", "ref": "صحیح مسلم 2055", "cats": ["daily"]}, {"id": 50, "title": "دودھ پینے کے بعد کی دعا", "arabic": "اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ", "urdu": "اے اللہ! ہمیں اس میں برکت دے اور ہمیں اس سے مزید عطا فرما۔ (دودھ کے علاوہ کھانے کے بعد: «وَأَطْعِمْنَا خَيْرًا مِنْهُ» یعنی اس سے بہتر کھانا عطا فرما۔)", "ref": "سنن ابو داود 3730، سنن ترمذی 3455", "cats": ["daily"]}, {"id": 51, "title": "نکاح پر مبارک باد کی دعا", "arabic": "بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ", "urdu": "اللہ تمہیں برکت دے، تم پر برکت نازل کرے اور تم دونوں کو خیر میں جمع رکھے۔", "ref": "سنن ابو داود 2130، سنن ترمذی 1091", "cats": ["other"]}, {"id": 52, "title": "نئی دلہن کی بھلائی کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ", "urdu": "اے اللہ! میں تجھ سے اس کی بھلائی اور اس کی فطرت میں رکھی ہوئی بھلائی مانگتا ہوں، اور اس کے شر اور اس کی فطرت میں رکھے ہوئے شر سے تیری پناہ مانگتا ہوں۔", "ref": "سنن ابو داود 2160، سنن ابن ماجہ 1918", "cats": ["other"]}, {"id": 53, "title": "شیطان کے شر سے اولاد کی حفاظت کی دعا", "arabic": "بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا", "urdu": "اللہ کے نام سے، اے اللہ! ہمیں شیطان سے بچا اور جو (اولاد) تو ہمیں دے اسے بھی شیطان سے بچا۔", "ref": "صحیح بخاری 141، صحیح مسلم 1434", "cats": ["magic_shaitan"]}, {"id": 54, "title": "مریض کے لیے مکمل شفا کی دعا", "arabic": "اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَاسَ، اشْفِهِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا", "urdu": "اے اللہ! لوگوں کے رب! تکلیف دور کر دے، شفا دے، تو ہی شفا دینے والا ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا دے جو کوئی بیماری باقی نہ چھوڑے۔", "ref": "صحیح بخاری 5675، صحیح مسلم 2191", "cats": ["illness"]}, {"id": 55, "title": "عیادت کے وقت سات بار پڑھنے کی دعا", "arabic": "أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ", "urdu": "میں عظمت والے اللہ، عرشِ عظیم کے رب سے سوال کرتا ہوں کہ وہ تمہیں شفا دے۔ (سات بار)", "ref": "سنن ابو داود 3106، سنن ترمذی 2083", "cats": ["illness"]}, {"id": 56, "title": "بیمار پر دم کی دعا", "arabic": "بِسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللَّهُ يَشْفِيكَ، بِسْمِ اللَّهِ أَرْقِيكَ", "urdu": "اللہ کے نام سے میں تم پر دم کرتا ہوں، ہر اس چیز سے جو تمہیں تکلیف دے، ہر جان کے شر اور حسد کرنے والی نظر سے۔ اللہ تمہیں شفا دے، اللہ کے نام سے میں تم پر دم کرتا ہوں۔", "ref": "صحیح مسلم 2186", "cats": ["evil_eye", "illness"]}, {"id": 57, "title": "درد کی جگہ ہاتھ رکھ کر پڑھنے کی دعا", "arabic": "أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ", "urdu": "میں اللہ کی عزت و قدرت کی پناہ لیتا ہوں اس تکلیف کے شر سے جو میں محسوس کرتا ہوں اور جس کا مجھے ڈر ہے۔ (درد کی جگہ ہاتھ رکھ کر، پہلے تین بار بسم اللہ اور پھر یہ دعا سات بار)", "ref": "صحیح مسلم 2202", "cats": ["illness"]}, {"id": 58, "title": "سفر میں کسی جگہ ٹھہرتے وقت کی دعا", "arabic": "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", "urdu": "میں اللہ کے مکمل کلمات کی پناہ لیتا ہوں اس کی ہر مخلوق کے شر سے۔", "ref": "صحیح مسلم 2709", "cats": ["magic_shaitan", "daily"]}, {"id": 59, "title": "بچوں کی حفاظت کے لیے دم کی دعا", "arabic": "أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ", "urdu": "میں تم دونوں کو اللہ کے مکمل کلمات کی پناہ میں دیتا ہوں، ہر شیطان، ہر زہریلے جانور اور ہر نقصان پہنچانے والی نظر سے۔", "ref": "صحیح بخاری 3371", "cats": ["evil_eye", "magic_shaitan", "illness"]}, {"id": 60, "title": "کان، آنکھ، زبان، دل اور شہوت کے شر سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي", "urdu": "اے اللہ! میں اپنے کان، اپنی آنکھ، اپنی زبان، اپنے دل اور اپنی شرم گاہ (کی خواہش) کے شر سے تیری پناہ مانگتا ہوں۔", "ref": "سنن ابو داود 1551، سنن ترمذی 3492، سنن نسائی 5444", "cats": ["other"]}, {"id": 61, "title": "سب سے افضل استغفار (سید الاستغفار)", "arabic": "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ", "urdu": "اے اللہ! تو میرا رب ہے، تیرے سوا کوئی معبود نہیں، تو نے مجھے پیدا کیا اور میں تیرا بندہ ہوں، اور جہاں تک مجھ سے ہو سکے تیرے عہد اور وعدے پر قائم ہوں۔ میں اپنے کیے کے شر سے تیری پناہ مانگتا ہوں، مجھ پر تیری نعمتوں کا اقرار کرتا ہوں اور اپنے گناہ کا بھی اقرار کرتا ہوں، پس مجھے بخش دے، کیونکہ تیرے سوا کوئی گناہ نہیں بخشتا۔", "ref": "صحیح بخاری 6306", "cats": ["morning", "evening", "istighfar"]}, {"id": 62, "title": "غم، فکر، کاہلی، بزدلی اور قرض کے بوجھ سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ", "urdu": "اے اللہ! میں فکر اور غم، بے بسی اور سستی، کنجوسی اور بزدلی، قرض کے بوجھ اور لوگوں کے غلبے سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح بخاری 6369", "cats": ["distress"]}, {"id": 63, "title": "قرآن کو دل کی بہار اور غم کا علاج بنانے کی دعا", "arabic": "اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي", "urdu": "اے اللہ! میں تیرا بندہ ہوں، تیرے بندے اور تیری بندی کا بیٹا ہوں، میری پیشانی تیرے ہاتھ میں ہے، مجھ میں تیرا حکم چلتا ہے اور میرے بارے میں تیرا فیصلہ عدل ہے۔ میں تجھ سے تیرے ہر اس نام کے وسیلے سے مانگتا ہوں جو تو نے اپنا رکھا، یا اپنی کتاب میں اتارا، یا اپنی مخلوق میں سے کسی کو سکھایا، یا اپنے علمِ غیب میں اپنے پاس رکھا، کہ تو قرآن کو میرے دل کی بہار، میرے سینے کا نور، میرے غم کو دور کرنے والا اور میری فکر کو ختم کرنے والا بنا دے۔", "ref": "مسند احمد 3704؛ السلسلہ الصحیحہ 199", "cats": ["distress"]}, {"id": 64, "title": "پریشانی اور بے چینی کے وقت کی دعا", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ", "urdu": "اللہ کے سوا کوئی معبود نہیں، وہ عظمت والا اور بردبار ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ عرشِ عظیم کا رب ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ آسمانوں کا رب، زمین کا رب اور عرشِ کریم کا رب ہے۔", "ref": "صحیح بخاری 6346، صحیح مسلم 2730", "cats": ["distress"]}, {"id": 65, "title": "فریاد اور مدد کی دعا", "arabic": "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ", "urdu": "اے زندہ! اے سب کو سنبھالنے والے! میں تیری رحمت کے وسیلے سے فریاد کرتا ہوں۔", "ref": "سنن ترمذی 3524", "cats": ["distress"]}, {"id": 66, "title": "اللہ پر بھروسے کا کلمہ", "arabic": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ", "urdu": "ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے۔", "ref": "صحیح بخاری 4563", "cats": ["distress"]}, {"id": 67, "title": "اپنے کیے اور نہ کیے ہوئے عمل کے شر سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ", "urdu": "اے اللہ! میں اس برائی سے تیری پناہ مانگتا ہوں جو میں نے کی، اور اس سے بھی جو میں نے نہیں کی۔", "ref": "صحیح مسلم 2716", "cats": ["other"]}, {"id": 68, "title": "سوتے وقت کی مختصر دعا", "arabic": "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا", "urdu": "اے اللہ! تیرے ہی نام سے میں مرتا (سوتا) ہوں اور جیتا (جاگتا) ہوں۔", "ref": "صحیح بخاری 6324", "cats": ["sleep"]}, {"id": 69, "title": "اللہ کے سپرد ہو جانے کی دعا (سونے سے پہلے)", "arabic": "اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ", "urdu": "اے اللہ! میں نے اپنی جان تیرے سپرد کر دی، اپنا معاملہ تجھے سونپ دیا، اپنا رخ تیری طرف کر لیا اور اپنی پشت تیرے سہارے پر رکھ دی، تیری امید اور تیرے خوف کے ساتھ۔ تجھ سے بچ کر کہیں پناہ اور نجات نہیں مگر تیری ہی طرف۔ میں تیری اس کتاب پر ایمان لایا جو تو نے اتاری اور تیرے اس نبی پر جسے تو نے بھیجا۔", "ref": "صحیح بخاری 247، صحیح مسلم 2710", "cats": ["sleep"]}, {"id": 70, "title": "قیامت کے دن عذاب سے بچاؤ کی دعا", "arabic": "اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ", "urdu": "اے اللہ! مجھے اپنے عذاب سے بچا لینا اس دن جب تو اپنے بندوں کو دوبارہ اٹھائے گا۔", "ref": "سنن ابو داود 5045، سنن ترمذی 3398", "cats": ["sleep"]}, {"id": 71, "title": "کھلانے، پلانے، کفایت اور ٹھکانہ دینے پر شکر", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ", "urdu": "تمام تعریف اس اللہ کے لیے ہے جس نے ہمیں کھلایا، پلایا، ہماری کفایت کی اور ہمیں ٹھکانہ دیا۔ کتنے ہی لوگ ہیں جن کا نہ کوئی کفایت کرنے والا ہے نہ ٹھکانہ دینے والا۔", "ref": "صحیح مسلم 2715", "cats": ["daily"]}, {"id": 72, "title": "رات کو آنکھ کھلنے پر کی دعا", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، الْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، اللَّهُمَّ اغْفِرْ لِي", "urdu": "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، بادشاہی اور تعریف اسی کی ہے اور وہ ہر چیز پر قادر ہے۔ تعریف اللہ کے لیے ہے، اللہ پاک ہے، اس کے سوا کوئی معبود نہیں، اللہ سب سے بڑا ہے، اور گناہ سے بچنے اور نیکی کرنے کی طاقت صرف اللہ ہی سے ہے۔ اے اللہ! مجھے بخش دے۔", "ref": "صحیح بخاری 1154", "cats": ["sleep"]}, {"id": 73, "title": "وتر میں ہدایت و حفاظت کی دعا (دعائے قنوت)", "arabic": "اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ", "urdu": "اے اللہ! جنہیں تو نے ہدایت دی ان میں مجھے بھی ہدایت دے، جنہیں عافیت دی ان میں مجھے بھی عافیت دے، جن کا تو والی بنا ان میں میرا بھی والی بن جا، جو تو نے عطا کیا اس میں برکت دے، اور اپنے فیصلے کی برائی سے مجھے بچا، کیونکہ تو فیصلہ کرتا ہے اور تجھ پر کوئی فیصلہ نہیں چل سکتا، اور جسے تو دوست بنا لے وہ ذلیل نہیں ہوتا۔ اے ہمارے رب! تو برکت والا اور بلند ہے۔", "ref": "سنن ابو داود 1425، سنن ترمذی 464، سنن نسائی 1745", "cats": ["salah"]}, {"id": 74, "title": "شبِ قدر کی دعا", "arabic": "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "urdu": "اے اللہ! تو بہت معاف کرنے والا ہے، معافی کو پسند کرتا ہے، پس مجھے معاف فرما دے۔", "ref": "سنن ترمذی 3513، سنن ابن ماجہ 3850", "cats": ["other"]}, {"id": 75, "title": "بارش دیکھ کر کی دعا", "arabic": "اللَّهُمَّ صَيِّبًا نَافِعًا", "urdu": "اے اللہ! اسے نفع دینے والی بارش بنا دے۔", "ref": "صحیح بخاری 1032", "cats": ["daily"]}, {"id": 76, "title": "بارش زیادہ ہو جائے تو یہ دعا", "arabic": "اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا", "urdu": "اے اللہ! ہمارے اردگرد برسا اور ہم پر نہ برسا۔", "ref": "صحیح بخاری 1014، صحیح مسلم 897", "cats": ["daily"]}, {"id": 77, "title": "بارش مانگنے کی دعا (استسقاء)", "arabic": "اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا مَرِيعًا نَافِعًا غَيْرَ ضَارٍّ، عَاجِلًا غَيْرَ آجِلٍ", "urdu": "اے اللہ! ہمیں ایسی بارش عطا فرما جو فریاد رسی کرے، خوشگوار ہو، سبزہ اگائے، نفع دے، نقصان نہ دے، جلد آئے اور دیر نہ کرے۔", "ref": "سنن ابو داود 1169", "cats": ["daily"]}, {"id": 78, "title": "تیز ہوا چلنے پر کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ", "urdu": "اے اللہ! میں تجھ سے اس (ہوا) کی بھلائی، جو کچھ اس میں ہے اس کی بھلائی اور جس کام کے لیے یہ بھیجی گئی اس کی بھلائی مانگتا ہوں، اور اس کے شر، اس میں موجود شر اور جس مقصد کے لیے بھیجی گئی اس کے شر سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح مسلم 899", "cats": ["daily"]}, {"id": 79, "title": "نیا چاند دیکھ کر کی دعا", "arabic": "اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ، وَالسَّلَامَةِ وَالْإِسْلَامِ، رَبِّي وَرَبُّكَ اللَّهُ", "urdu": "اے اللہ! اس چاند کو ہم پر امن و ایمان اور سلامتی و اسلام کے ساتھ طلوع فرما۔ (اے چاند!) میرا اور تیرا رب اللہ ہے۔", "ref": "سنن ترمذی 3451", "cats": ["daily"]}, {"id": 80, "title": "دشمن کے شر سے حفاظت کی دعا", "arabic": "اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ", "urdu": "اے اللہ! ہم تجھے ان کے مقابل رکھتے ہیں اور ان کی برائیوں سے تیری پناہ مانگتے ہیں۔", "ref": "سنن ابو داود 1537", "cats": ["distress"]}, {"id": 81, "title": "ظالم دشمنوں کے مقابلے میں مدد کی دعا", "arabic": "اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الْأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ", "urdu": "اے اللہ! کتاب اتارنے والے، جلد حساب لینے والے! دشمن گروہوں کو شکست دے۔ اے اللہ! انہیں شکست دے اور ان کو ہلا ڈال۔", "ref": "صحیح بخاری 2933، صحیح مسلم 1742", "cats": ["distress"]}, {"id": 82, "title": "نمازِ جنازہ میں میت کے لیے جامع دعا", "arabic": "اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ", "urdu": "اے اللہ! اسے بخش دے، اس پر رحم فرما، اسے عافیت دے اور معاف کر دے، اس کی مہمانی عزت والی بنا، اس کی قبر کشادہ کر دے، اسے پانی، برف اور اولوں سے دھو دے، اور گناہوں سے ایسا صاف کر دے جیسے سفید کپڑا میل سے صاف کیا جاتا ہے۔", "ref": "صحیح مسلم 963", "cats": ["janaza"]}, {"id": 83, "title": "نمازِ جنازہ میں سب مسلمانوں کے لیے دعا", "arabic": "اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ", "urdu": "اے اللہ! ہمارے زندوں اور مُردوں، حاضر اور غائب، چھوٹوں اور بڑوں، مردوں اور عورتوں کو بخش دے۔ اے اللہ! ہم میں سے جسے تو زندہ رکھے اسے اسلام پر زندہ رکھ، اور جسے وفات دے اسے ایمان پر وفات دے۔", "ref": "سنن ابو داود 3201، سنن ترمذی 1024، سنن ابن ماجہ 1498", "cats": ["janaza"]}, {"id": 84, "title": "قبرستان جاتے وقت کی دعا", "arabic": "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ", "urdu": "اے مومن اور مسلمان بستی والو! تم پر سلامتی ہو، ان شاء اللہ ہم بھی تم سے آ ملنے والے ہیں۔ میں اللہ سے اپنے اور تمہارے لیے عافیت مانگتا ہوں۔", "ref": "صحیح مسلم 975", "cats": ["janaza"]}, {"id": 85, "title": "غم زدہ خاندان سے تعزیت کے الفاظ", "arabic": "إِنَّ لِلَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى", "urdu": "بے شک جو اللہ نے لے لیا وہ بھی اسی کا ہے اور جو دیا وہ بھی اسی کا ہے، اور ہر چیز اس کے ہاں ایک مقرر وقت کے ساتھ ہے۔", "ref": "صحیح بخاری 1284، صحیح مسلم 923", "cats": ["janaza"]}, {"id": 86, "title": "مصیبت پہنچنے پر کی دعا", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا", "urdu": "ہم اللہ کے ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں۔ اے اللہ! مجھے میری مصیبت میں اجر دے اور اس کے بدلے مجھے اس سے بہتر عطا فرما۔", "ref": "صحیح مسلم 918", "cats": ["distress"]}, {"id": 87, "title": "چھینک پر دعا دینے والے کو جواب", "arabic": "يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ", "urdu": "اللہ تمہیں ہدایت دے اور تمہارا حال درست کر دے۔ (جب چھینکنے والا «الحمد للہ» کہے اور سننے والا «یرحمک اللہ» کہے تو چھینکنے والا یہ کہے۔)", "ref": "صحیح بخاری 6224", "cats": ["daily"]}, {"id": 88, "title": "کسی مصیبت زدہ کو دیکھ کر شکر کی دعا", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا", "urdu": "تمام تعریف اس اللہ کے لیے ہے جس نے مجھے اس (مصیبت) سے بچا لیا جس میں تجھے ڈالا، اور مجھے اپنی بہت سی مخلوق پر فضیلت دی۔ (یہ دعا دل میں پڑھیں، مصیبت زدہ کو سنا کر نہیں۔)", "ref": "سنن ترمذی 3431", "cats": ["illness"]}, {"id": 89, "title": "بازار میں داخل ہوتے وقت کی دعا", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "urdu": "اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، بادشاہی اور تعریف اسی کی ہے، وہی زندگی دیتا اور موت دیتا ہے، وہ ہمیشہ زندہ ہے اسے موت نہیں، ہر بھلائی اسی کے ہاتھ میں ہے اور وہ ہر چیز پر قادر ہے۔", "ref": "سنن ترمذی 3428، سنن ابن ماجہ 2235", "cats": ["daily"]}, {"id": 90, "title": "سفر پر جانے والے کو رخصت کرنے کی دعا", "arabic": "أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ", "urdu": "میں تمہارا دین، تمہاری امانت اور تمہارے آخری اعمال اللہ کے سپرد کرتا ہوں۔", "ref": "سنن ابو داود 2600، سنن ترمذی 3443", "cats": ["daily"]}, {"id": 91, "title": "مسافر کے لیے تقویٰ اور آسانی کی دعا", "arabic": "زَوَّدَكَ اللَّهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُ مَا كُنْتَ", "urdu": "اللہ تمہیں تقویٰ کا زادِ راہ دے، تمہارا گناہ بخش دے اور تم جہاں بھی رہو تمہارے لیے بھلائی آسان کر دے۔", "ref": "سنن ترمذی 3444", "cats": ["daily"]}, {"id": 92, "title": "احسان کرنے والے کا شکریہ ادا کرنے کی دعا", "arabic": "جَزَاكَ اللَّهُ خَيْرًا", "urdu": "اللہ تمہیں بہترین بدلہ دے۔", "ref": "سنن ترمذی 2035", "cats": ["daily"]}, {"id": 93, "title": "قرض لوٹاتے وقت قرض دینے والے کے لیے دعا", "arabic": "بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالْأَدَاءُ", "urdu": "اللہ تمہارے گھر والوں اور مال میں برکت دے۔ قرض کا بدلہ تو شکر گزاری اور ادائیگی ہی ہے۔", "ref": "سنن نسائی 4683، سنن ابن ماجہ 2424", "cats": ["daily"]}, {"id": 94, "title": "مسجد میں داخل ہوتے وقت شیطان سے پناہ", "arabic": "أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ", "urdu": "میں عظمت والے اللہ کی، اس کے کریم چہرے کی اور اس کی قدیم بادشاہی کی پناہ لیتا ہوں، مردود شیطان سے۔", "ref": "سنن ابو داود 466", "cats": ["magic_shaitan", "daily"]}, {"id": 95, "title": "مسجد میں داخل ہوتے وقت رحمت کے دروازے کھلنے کی دعا", "arabic": "بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ", "urdu": "اللہ کے نام سے، اور اللہ کے رسول پر درود و سلام ہو۔ اے اللہ! میرے لیے اپنی رحمت کے دروازے کھول دے۔", "ref": "سنن ابن ماجہ 771؛ صحیح مسلم 713 (دعا کا آخری حصہ)", "cats": ["daily"]}, {"id": 96, "title": "سفر سے واپسی کی دعا", "arabic": "آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ", "urdu": "ہم لوٹنے والے ہیں، توبہ کرنے والے ہیں، عبادت کرنے والے ہیں اور اپنے رب کی تعریف کرنے والے ہیں۔", "ref": "صحیح مسلم 1342", "cats": ["daily"]}, {"id": 97, "title": "نیکی مکمل ہونے پر شکر کی دعا", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ", "urdu": "تمام تعریف اس اللہ کے لیے ہے جس کی نعمت سے نیک کام مکمل ہوتے ہیں۔", "ref": "سنن ابن ماجہ 3803", "cats": ["daily"]}, {"id": 98, "title": "غصہ آنے پر پڑھنے کی دعا", "arabic": "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", "urdu": "میں مردود شیطان سے اللہ کی پناہ مانگتا ہوں۔", "ref": "صحیح بخاری 6115، صحیح مسلم 2610", "cats": ["magic_shaitan"]}, {"id": 99, "title": "نماز کے بعد اللہ کی عطا اور روک کا اقرار", "arabic": "اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ", "urdu": "اے اللہ! جو تو دے اسے کوئی روکنے والا نہیں، اور جو تو روک لے اسے کوئی دینے والا نہیں، اور کسی مال دار یا بڑے مرتبے والے کو اس کا مرتبہ تیرے مقابلے میں فائدہ نہیں دیتا۔", "ref": "صحیح بخاری 844، صحیح مسلم 593", "cats": ["salah"]}, {"id": 100, "title": "سلام پھیرنے کے بعد کی مختصر دعا", "arabic": "اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ", "urdu": "اے اللہ! تو سلامتی والا ہے، سلامتی تجھی سے ہے، اے عظمت اور احسان والے! تو برکت والا ہے۔", "ref": "صحیح مسلم 591", "cats": ["salah"]}, {"id": 101, "title": "جنت کا خزانہ", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "urdu": "گناہ سے بچنے کی طاقت اور نیکی کرنے کی قوت صرف اللہ کی مدد سے ہے۔", "ref": "صحیح بخاری 6384، صحیح مسلم 2704", "cats": ["other"]}, {"id": 102, "title": "زبان پر ہلکے اور میزان میں بھاری دو کلمے", "arabic": "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ", "urdu": "اللہ پاک ہے اور اپنی تعریف کے ساتھ ہے، عظمت والا اللہ پاک ہے۔", "ref": "صحیح بخاری 6406، صحیح مسلم 2694", "cats": ["other"]}, {"id": 103, "title": "تسبیح بے شمار گنتی کے ساتھ", "arabic": "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ", "urdu": "اللہ پاک ہے اور اپنی تعریف کے ساتھ ہے، اس کی مخلوق کی گنتی کے برابر، اس کی رضا کے برابر، اس کے عرش کے وزن کے برابر اور اس کے کلمات کی سیاہی کے برابر۔", "ref": "صحیح مسلم 2726", "cats": ["other"]}, {"id": 104, "title": "ہر گناہ کی بخشش کا استغفار", "arabic": "أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ", "urdu": "میں اللہ سے بخشش مانگتا ہوں جس کے سوا کوئی معبود نہیں، وہ زندہ اور سب کو قائم رکھنے والا ہے، اور میں اس کی طرف توبہ کرتا ہوں۔", "ref": "سنن ابو داود 1517، سنن ترمذی 3577", "cats": ["istighfar"]}, {"id": 105, "title": "توبہ کی قبولیت کی دعا", "arabic": "رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ", "urdu": "اے میرے رب! مجھے بخش دے اور میری توبہ قبول فرما، بے شک تو ہی توبہ قبول کرنے والا، رحم کرنے والا ہے۔", "ref": "سنن ابو داود 1516، سنن ترمذی 3434", "cats": ["istighfar"]}, {"id": 106, "title": "نبی ﷺ پر درود (درودِ ابراہیمی)", "arabic": "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "urdu": "اے اللہ! محمد ﷺ اور آلِ محمد پر رحمت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر رحمت نازل فرمائی، بے شک تو تعریف والا، بزرگی والا ہے۔ اے اللہ! محمد ﷺ اور آلِ محمد پر برکت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر برکت نازل فرمائی، بے شک تو تعریف والا، بزرگی والا ہے۔", "ref": "صحیح بخاری 3370", "cats": ["salah"]}, {"id": 107, "title": "برا خواب دیکھ کر پناہ مانگنے کی دعا", "arabic": "أَعُوذُ بِاللَّهِ مِنْ شَرِّهَا", "urdu": "میں اس (خواب) کے شر سے اللہ کی پناہ مانگتا ہوں۔ (بائیں طرف تین بار ہلکا سا تھوک دیں اور کروٹ بدل لیں، کسی کو خواب نہ سنائیں۔)", "ref": "صحیح بخاری 6986، صحیح مسلم 2261", "cats": ["sleep"]}, {"id": 108, "title": "آخری وقت میں اعلیٰ رفاقت کی دعا", "arabic": "اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى", "urdu": "اے اللہ! مجھے بخش دے، مجھ پر رحم فرما اور مجھے بلند ترین رفیقوں (انبیاء و صالحین) کے ساتھ ملا دے۔", "ref": "صحیح بخاری 5674، صحیح مسلم 2444", "cats": ["illness"]}, {"id": 109, "title": "صبح کی جامع دعا (ملک اللہ کا)", "arabic": "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ", "urdu": "ہم نے صبح کی اور اللہ کی بادشاہی نے صبح کی، تعریف اللہ کے لیے ہے، اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، بادشاہی اور تعریف اسی کی ہے اور وہ ہر چیز پر قادر ہے۔ اے میرے رب! میں تجھ سے اس دن کی بھلائی اور اس کے بعد کی بھلائی مانگتا ہوں، اور اس دن کے شر اور اس کے بعد کے شر سے تیری پناہ مانگتا ہوں۔ اے میرے رب! سستی اور بڑھاپے کی خرابی سے تیری پناہ مانگتا ہوں۔ اے میرے رب! جہنم کے عذاب اور قبر کے عذاب سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح مسلم 2723", "cats": ["morning"]}, {"id": 110, "title": "صبح و شام اللہ ہی کے سہارے جینے کی دعا", "arabic": "اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ", "urdu": "اے اللہ! تیرے ہی (حکم اور مدد) سے ہم نے صبح کی، تیرے ہی سے شام کی، تیرے ہی سے جیتے ہیں اور تیرے ہی سے مرتے ہیں، اور تیری ہی طرف اٹھ کر جانا ہے۔", "ref": "سنن ابو داود 5068، سنن ترمذی 3391", "cats": ["morning", "evening"]}, {"id": 111, "title": "نفس اور شیطان کے شر اور شرک سے پناہ", "arabic": "اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ", "urdu": "اے اللہ! غیب اور ظاہر کے جاننے والے، آسمانوں اور زمین کو پیدا کرنے والے، ہر چیز کے رب اور مالک! میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں۔ میں اپنے نفس کے شر سے اور شیطان کے شر اور اس کے شرک (کی دعوت) سے تیری پناہ مانگتا ہوں۔", "ref": "سنن ابو داود 5067، سنن ترمذی 3392", "cats": ["morning", "evening", "magic_shaitan"]}, {"id": 112, "title": "ہر نقصان سے حفاظت کی دعا (صبح و شام تین بار)", "arabic": "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ", "urdu": "اس اللہ کے نام سے جس کے نام کے ساتھ زمین و آسمان میں کوئی چیز نقصان نہیں پہنچا سکتی، اور وہ خوب سننے والا، خوب جاننے والا ہے۔", "ref": "سنن ابو داود 5088، سنن ترمذی 3388", "cats": ["morning", "evening", "magic_shaitan"]}, {"id": 113, "title": "جنت واجب کرنے والا اقرار", "arabic": "رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا", "urdu": "میں اللہ کے رب ہونے، اسلام کے دین ہونے اور محمد ﷺ کے نبی ہونے پر راضی ہوں۔", "ref": "سنن ابو داود 1529", "cats": ["morning", "evening"]}, {"id": 114, "title": "نماز کی ابتدائی دعا (ثنا)", "arabic": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ", "urdu": "اے اللہ! تو پاک ہے اور اپنی تعریف کے ساتھ ہے، تیرا نام برکت والا ہے، تیری شان بلند ہے اور تیرے سوا کوئی معبود نہیں۔", "ref": "سنن ابو داود 775، سنن ترمذی 242", "cats": ["salah"]}, {"id": 115, "title": "نماز کی ابتدا میں اللہ کی بڑائی اور حمد", "arabic": "اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا", "urdu": "اللہ سب سے بڑا ہے، بہت بڑا؛ تعریف اللہ کے لیے ہے، بہت زیادہ؛ اور اللہ صبح و شام پاک ہے۔", "ref": "صحیح مسلم 601", "cats": ["salah"]}, {"id": 116, "title": "رکوع کے بعد کی دعا", "arabic": "رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ", "urdu": "اے ہمارے رب! تعریف تیرے ہی لیے ہے، بہت زیادہ، پاکیزہ اور برکت والی تعریف۔", "ref": "صحیح بخاری 799", "cats": ["salah"]}, {"id": 117, "title": "نماز کا قعدہ (تشہد)", "arabic": "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "urdu": "تمام زبانی، بدنی اور مالی عبادتیں اللہ ہی کے لیے ہیں۔ اے نبی! آپ پر سلام اور اللہ کی رحمت و برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، اور گواہی دیتا ہوں کہ محمد ﷺ اس کے بندے اور رسول ہیں۔", "ref": "صحیح بخاری 831، صحیح مسلم 402", "cats": ["salah"]}, {"id": 118, "title": "تشہد کے بعد چار چیزوں سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ", "urdu": "اے اللہ! میں جہنم کے عذاب سے، قبر کے عذاب سے، زندگی اور موت کے فتنوں سے اور مسیح دجال کے فتنے کے شر سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح مسلم 588", "cats": ["salah"]}, {"id": 119, "title": "اپنے اوپر بہت زیادتی کے اعتراف کی دعا", "arabic": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ", "urdu": "اے اللہ! میں نے اپنی جان پر بہت زیادہ ظلم کیا، اور تیرے سوا کوئی گناہ نہیں بخشتا، پس اپنی طرف سے خاص بخشش کے ساتھ مجھے بخش دے اور مجھ پر رحم فرما، بے شک تو ہی بخشنے والا، رحم کرنے والا ہے۔", "ref": "صحیح بخاری 834، صحیح مسلم 2705", "cats": ["istighfar"]}, {"id": 120, "title": "صبح سویرے کام میں برکت کی دعا", "arabic": "اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي بُكُورِهَا", "urdu": "اے اللہ! میری امت کے لیے ان کی صبح کے وقت (کام کے آغاز) میں برکت دے۔", "ref": "سنن ابو داود 2606، سنن ترمذی 1212، سنن ابن ماجہ 2236", "cats": ["morning"]}, {"id": 121, "title": "بیت الخلاء میں داخل ہوتے وقت کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ", "urdu": "اے اللہ! میں ناپاک نر اور مادہ شیاطین سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح بخاری 142، صحیح مسلم 375", "cats": ["magic_shaitan", "daily"]}, {"id": 122, "title": "بیت الخلاء سے نکلتے وقت کی دعا", "arabic": "غُفْرَانَكَ", "urdu": "(اے اللہ!) میں تجھ سے بخشش مانگتا ہوں۔", "ref": "سنن ابو داود 30، سنن ترمذی 7", "cats": ["daily"]}, {"id": 123, "title": "وضو کے بعد جنت کے آٹھوں دروازے کھلنے کی دعا", "arabic": "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "urdu": "میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اور گواہی دیتا ہوں کہ محمد ﷺ اس کے بندے اور رسول ہیں۔", "ref": "صحیح مسلم 234", "cats": ["salah"]}, {"id": 124, "title": "اذان کے بعد نبی ﷺ کے لیے وسیلہ مانگنے کی دعا", "arabic": "اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ", "urdu": "اے اللہ! اس کامل پکار اور قائم ہونے والی نماز کے رب! محمد ﷺ کو وسیلہ اور فضیلت عطا فرما اور انہیں وہ مقامِ محمود دے جس کا تو نے ان سے وعدہ کیا ہے۔", "ref": "صحیح بخاری 614", "cats": ["salah"]}, {"id": 125, "title": "اذان سن کر شہادت اور رضا کا اقرار", "arabic": "وَأَنَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا", "urdu": "اور میں بھی گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اور محمد ﷺ اس کے بندے اور رسول ہیں۔ میں اللہ کے رب ہونے، محمد ﷺ کے رسول ہونے اور اسلام کے دین ہونے پر راضی ہوں۔ (مؤذن کے «اشہد ان محمدا رسول اللہ» کے بعد پڑھیں۔)", "ref": "صحیح مسلم 386", "cats": ["salah"]}, {"id": 126, "title": "سجدے میں ہر قسم کے گناہ کی معافی کی دعا", "arabic": "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ", "urdu": "اے اللہ! میرے سارے گناہ بخش دے، چھوٹے اور بڑے، پہلے اور پچھلے، ظاہر اور چھپے۔", "ref": "صحیح مسلم 483", "cats": ["salah", "istighfar"]}, {"id": 127, "title": "سجدے میں اللہ کی تخلیق پر سجدہ ریزی کی دعا", "arabic": "اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ", "urdu": "اے اللہ! میں نے تیرے ہی لیے سجدہ کیا، تجھ پر ایمان لایا اور تیرے ہی آگے سرِ تسلیم خم کیا۔ میرے چہرے نے اس ذات کو سجدہ کیا جس نے اسے پیدا کیا، اس کی صورت بنائی اور اس کے کان اور آنکھیں کھول دیں۔ بہترین پیدا کرنے والا اللہ بڑی برکت والا ہے۔", "ref": "صحیح مسلم 771", "cats": ["salah"]}, {"id": 128, "title": "آگ، قبر اور مال و فقر کے فتنے سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ، وَعَذَابِ النَّارِ، وَفِتْنَةِ الْقَبْرِ، وَعَذَابِ الْقَبْرِ، وَشَرِّ فِتْنَةِ الْغِنَى، وَشَرِّ فِتْنَةِ الْفَقْرِ", "urdu": "اے اللہ! میں آگ کی آزمائش اور آگ کے عذاب سے، قبر کی آزمائش اور قبر کے عذاب سے، مال داری کی آزمائش کے شر سے اور فقر کی آزمائش کے شر سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح بخاری 6368، صحیح مسلم 589", "cats": ["salah"]}, {"id": 129, "title": "گناہ اور قرض سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ", "urdu": "اے اللہ! میں گناہ اور قرض (کے بوجھ) سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح بخاری 832", "cats": ["salah", "distress"]}, {"id": 130, "title": "کنجوسی، بزدلی، بڑھاپے کی کمزوری اور دنیا کے فتنے سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ", "urdu": "اے اللہ! میں کنجوسی سے تیری پناہ مانگتا ہوں، بزدلی سے تیری پناہ مانگتا ہوں، اس سے پناہ مانگتا ہوں کہ نکمی (بوڑھی) عمر کی طرف لوٹایا جاؤں، اور دنیا کے فتنے اور قبر کے عذاب سے تیری پناہ مانگتا ہوں۔", "ref": "صحیح بخاری 2822", "cats": ["other"]}, {"id": 131, "title": "نفس کو تقویٰ اور پاکیزگی دینے کی دعا", "arabic": "اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا", "urdu": "اے اللہ! میرے نفس کو اس کا تقویٰ عطا فرما اور اسے پاک کر دے، تو ہی سب سے بہتر پاک کرنے والا ہے، تو ہی اس کا کارساز اور مالک ہے۔", "ref": "صحیح مسلم 2722 (اسی حدیث کا پہلا حصہ جو دعا نمبر 7 میں ہے)", "cats": ["other"]}, {"id": 132, "title": "محتاجی، کمی، ذلت اور ظلم سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ، وَأَعُوذُ بِكَ مِنْ أَنْ أَظْلِمَ أَوْ أُظْلَمَ", "urdu": "اے اللہ! میں محتاجی، کمی اور ذلت سے تیری پناہ مانگتا ہوں، اور اس سے بھی کہ میں کسی پر ظلم کروں یا مجھ پر ظلم کیا جائے۔", "ref": "سنن ابو داود 1544، سنن نسائی 5460", "cats": ["distress"]}, {"id": 133, "title": "مدد، ہدایت اور شکر گزاری کی نہایت جامع دعا", "arabic": "رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الْهُدَى إِلَيَّ، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مِطْوَاعًا، إِلَيْكَ مُخْبِتًا، أَوْ مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَثَبِّتْ حُجَّتِي، وَاهْدِ قَلْبِي، وَسَدِّدْ لِسَانِي، وَاسْلُلْ سَخِيمَةَ قَلْبِي", "urdu": "اے میرے رب! میری مدد فرما اور میرے خلاف کسی کی مدد نہ کر، مجھے غلبہ دے اور میرے خلاف کسی کو غلبہ نہ دے، میرے حق میں تدبیر فرما اور میرے خلاف تدبیر نہ ہونے دے، مجھے ہدایت دے اور ہدایت کو میرے لیے آسان کر دے، اور جو مجھ پر زیادتی کرے اس کے مقابلے میں میری مدد کر۔ اے میرے رب! مجھے اپنا بہت شکر گزار، بہت ذکر کرنے والا، بہت ڈرنے والا، بہت فرماں بردار، اور عاجزی کے ساتھ تیری طرف رجوع کرنے والا بنا دے۔ اے میرے رب! میری توبہ قبول فرما، میرے گناہ دھو دے، میری دعا قبول فرما، میری دلیل کو مضبوط رکھ، میرے دل کو ہدایت دے، میری زبان کو درست رکھ اور میرے دل کی کدورت نکال دے۔", "ref": "سنن ابو داود 1510، سنن ترمذی 3551، سنن ابن ماجہ 3830", "cats": ["distress"]}, {"id": 134, "title": "کان، آنکھ اور طاقت کے آخر تک باقی رہنے کی دعا", "arabic": "اللَّهُمَّ مَتِّعْنِي بِسَمْعِي وَبَصَرِي، وَاجْعَلْهُمَا الْوَارِثَ مِنِّي، وَانْصُرْنِي عَلَى مَنْ ظَلَمَنِي، وَخُذْ مِنْهُ بِثَأْرِي", "urdu": "اے اللہ! مجھے میرے کان اور آنکھ سے فائدہ دے اور انہیں آخر تک میرے ساتھ باقی رکھ، جس نے مجھ پر ظلم کیا اس کے مقابلے میں میری مدد کر اور اس سے میرا انصاف دلوا۔", "ref": "سنن ترمذی 3604", "cats": ["other"]}, {"id": 135, "title": "کھانے کی ابتدا میں بسم اللہ بھول جائے تو یہ کہے", "arabic": "بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ", "urdu": "اللہ کے نام سے، اس کے شروع میں بھی اور اس کے آخر میں بھی۔", "ref": "سنن ابو داود 3767، سنن ترمذی 1858", "cats": ["daily"]}, {"id": 136, "title": "کھانے کے بعد شکر اور مغفرت کی دعا", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ", "urdu": "تمام تعریف اس اللہ کے لیے ہے جس نے مجھے یہ کھلایا اور مجھے رزق دیا، میری کسی طاقت اور قوت کے بغیر۔ (حدیث کے مطابق اس سے اگلے پچھلے گناہ معاف ہوتے ہیں۔)", "ref": "سنن ابو داود 3850، سنن ترمذی 3458، سنن ابن ماجہ 3285", "cats": ["daily"]}, {"id": 137, "title": "نیا کپڑا پہنتے وقت کی دعا", "arabic": "اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ", "urdu": "اے اللہ! تیرے ہی لیے تعریف ہے، تو نے مجھے یہ پہنایا۔ میں تجھ سے اس کی بھلائی اور اس بھلائی کا سوال کرتا ہوں جس کے لیے یہ بنایا گیا، اور اس کے شر اور اس شر سے پناہ مانگتا ہوں جس کے لیے یہ بنایا گیا۔", "ref": "سنن ابو داود 4020، سنن ترمذی 1767", "cats": ["daily"]}, {"id": 138, "title": "کپڑا پہننے پر شکر کی دعا", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ", "urdu": "تمام تعریف اس اللہ کے لیے ہے جس نے مجھے یہ پہنایا اور رزق دیا، میری کسی طاقت اور قوت کے بغیر۔", "ref": "سنن ابو داود 4023", "cats": ["daily"]}, {"id": 139, "title": "مال، اولاد اور برکت کی دعا", "arabic": "اللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ، وَبَارِكْ لَهُ فِيمَا أَعْطَيْتَهُ", "urdu": "اے اللہ! اس کے مال اور اولاد میں اضافہ فرما اور جو کچھ تو نے اسے دیا اس میں برکت دے۔", "ref": "صحیح بخاری 6334، صحیح مسلم 660", "cats": ["other"]}, {"id": 140, "title": "بچے کے لیے علمِ کتاب کی دعا", "arabic": "اللَّهُمَّ عَلِّمْهُ الْكِتَابَ", "urdu": "اے اللہ! اسے کتاب (قرآن و دین) کا علم سکھا دے۔", "ref": "صحیح بخاری 75", "cats": ["daily"]}, {"id": 141, "title": "مدینہ کی محبت کی دعا", "arabic": "اللَّهُمَّ حَبِّبْ إِلَيْنَا الْمَدِينَةَ كَحُبِّنَا مَكَّةَ أَوْ أَشَدَّ", "urdu": "اے اللہ! ہمارے دل میں مدینہ کی محبت ڈال دے، جیسے ہمیں مکہ سے محبت ہے بلکہ اس سے بھی زیادہ۔", "ref": "صحیح بخاری 1889، صحیح مسلم 1376", "cats": ["other"]}, {"id": 142, "title": "مریض کی عیادت پر تسلی کے الفاظ", "arabic": "لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللَّهُ", "urdu": "کوئی حرج نہیں، ان شاء اللہ (یہ بیماری گناہوں سے) پاک کرنے والی ہے۔", "ref": "صحیح بخاری 3616", "cats": ["illness"]}, {"id": 143, "title": "زخم یا تکلیف پر مٹی سے دم کی دعا", "arabic": "بِسْمِ اللَّهِ، تُرْبَةُ أَرْضِنَا، بِرِيقَةِ بَعْضِنَا، يُشْفَى سَقِيمُنَا، بِإِذْنِ رَبِّنَا", "urdu": "اللہ کے نام سے، ہماری زمین کی مٹی، ہم میں سے کسی کے لعاب کے ساتھ، ہمارا بیمار ہمارے رب کے حکم سے شفا پائے گا۔", "ref": "صحیح بخاری 5745، صحیح مسلم 2194", "cats": ["illness"]}, {"id": 144, "title": "حج و عمرہ کا تلبیہ", "arabic": "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ", "urdu": "میں حاضر ہوں، اے اللہ! میں حاضر ہوں، میں حاضر ہوں، تیرا کوئی شریک نہیں، میں حاضر ہوں۔ بے شک تمام تعریف اور نعمت تیری ہی ہے اور بادشاہی بھی، تیرا کوئی شریک نہیں۔", "ref": "صحیح بخاری 1549، صحیح مسلم 1184", "cats": ["other"]}, {"id": 145, "title": "مصیبت اور تنگی سے نکلنے کی دعائے یونس", "arabic": "لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ", "urdu": "تیرے سوا کوئی معبود نہیں، تو پاک ہے، بے شک میں ہی ظالموں میں سے تھا۔", "ref": "سنن ترمذی 3505", "cats": ["distress"]}, {"id": 146, "title": "صبح کو فطرتِ اسلام پر ہونے کا اقرار", "arabic": "أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ", "urdu": "ہم نے فطرتِ اسلام پر، کلمۂ اخلاص پر، اپنے نبی محمد ﷺ کے دین پر اور اپنے باپ ابراہیم کی ملت پر صبح کی، جو یکسو مسلمان تھے اور مشرکوں میں سے نہ تھے۔", "ref": "مسند احمد 15367", "cats": ["morning"]}, {"id": 147, "title": "بُرے پڑوسی سے پناہ", "arabic": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ السُّوءِ فِي دَارِ الْمُقَامَةِ، فَإِنَّ جَارَ الْبَادِيَةِ يَتَحَوَّلُ", "urdu": "اے اللہ! میں مستقل رہنے کی جگہ میں بُرے پڑوسی سے تیری پناہ مانگتا ہوں، کیونکہ صحرا کا پڑوسی تو (جلد) چلا جاتا ہے۔", "ref": "الادب المفرد 117؛ سنن نسائی 5502", "cats": ["daily"]}, {"id": 148, "title": "میت کو قبر میں رکھتے وقت کی دعا", "arabic": "بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُولِ اللَّهِ", "urdu": "اللہ کے نام سے اور رسول اللہ ﷺ کی سنت کے مطابق (ہم اسے رکھتے ہیں)۔", "ref": "سنن ابو داود 3213، سنن ترمذی 1046", "cats": ["janaza"]}, {"id": 149, "title": "تدفین کے بعد میت کے لیے ثابت قدمی کی دعا", "arabic": "اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ثَبِّتْهُ", "urdu": "اے اللہ! اسے بخش دے، اے اللہ! اسے (سوالات کے وقت) ثابت قدم رکھ۔", "ref": "سنن ابو داود 3221", "cats": ["janaza"]}, {"id": 150, "title": "مرنے والے کی آنکھیں بند کرتے وقت کی دعا", "arabic": "اللَّهُمَّ اغْفِرْ لِفُلَانٍ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ", "urdu": "اے اللہ! فلاں (میت کا نام) کو بخش دے، ہدایت یافتہ لوگوں میں اس کا درجہ بلند فرما، اس کے پیچھے رہ جانے والوں میں تو اس کا جانشین بن، اے سب جہانوں کے رب! ہمیں اور اسے بخش دے، اس کی قبر کشادہ کر دے اور اس میں اس کے لیے روشنی کر دے۔", "ref": "صحیح مسلم 920", "cats": ["janaza"]}, {"id": 151, "title": "مدینہ کے پھلوں، پیمانوں اور شہر میں برکت کی دعا", "arabic": "اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا", "urdu": "اے اللہ! ہمارے پھلوں میں برکت دے، ہمارے شہر میں برکت دے، ہمارے صاع میں برکت دے اور ہمارے مُد (ناپنے کے پیمانوں) میں برکت دے۔", "ref": "صحیح مسلم 1373", "cats": ["other"]}, {"id": 152, "title": "شام اور یمن کے لیے برکت کی دعا", "arabic": "اللَّهُمَّ بَارِكْ لَنَا فِي شَامِنَا، اللَّهُمَّ بَارِكْ لَنَا فِي يَمَنِنَا", "urdu": "اے اللہ! ہمارے شام میں ہمیں برکت دے، اے اللہ! ہمارے یمن میں ہمیں برکت دے۔", "ref": "صحیح بخاری 1037", "cats": ["other"]}, {"id": 153, "title": "آخرت کی زندگی کو اصل جاننے اور مہاجرین و انصار کی مغفرت کی دعا", "arabic": "اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ الْآخِرَةِ، فَاغْفِرْ لِلْأَنْصَارِ وَالْمُهَاجِرَةِ", "urdu": "اے اللہ! اصل زندگی تو آخرت ہی کی زندگی ہے، پس انصار اور مہاجرین کو بخش دے۔", "ref": "صحیح بخاری 2834، صحیح مسلم 1805", "cats": ["other"]}, {"id": 154, "title": "اللہ کی راہ میں شہادت اور مدینہ میں موت کی دعا", "arabic": "اللَّهُمَّ ارْزُقْنِي شَهَادَةً فِي سَبِيلِكَ، وَاجْعَلْ مَوْتِي فِي بَلَدِ رَسُولِكَ", "urdu": "اے اللہ! مجھے اپنی راہ میں شہادت نصیب فرما اور میری موت اپنے رسول ﷺ کے شہر میں مقدر فرما۔", "ref": "صحیح بخاری 1890", "cats": ["other"]}, {"id": 155, "title": "ظالموں کے مقابلے میں اللہ سے کفایت مانگنے کی دعا", "arabic": "اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ", "urdu": "اے اللہ! تو جس طرح چاہے ان (ظالموں) کے مقابلے میں میری کفایت فرما۔", "ref": "صحیح مسلم 3005", "cats": ["distress"]}, {"id": 156, "title": "کروٹ لیتے وقت جان کی حفاظت کی دعا", "arabic": "بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ", "urdu": "اے میرے رب! تیرے نام سے میں نے اپنا پہلو (بستر پر) رکھا اور تیرے ہی نام سے اسے اٹھاؤں گا۔ اگر تو میری جان روک لے تو اس پر رحم فرما، اور اگر اسے چھوڑ دے تو اس کی ایسے حفاظت فرما جیسے تو اپنے نیک بندوں کی حفاظت کرتا ہے۔", "ref": "صحیح بخاری 6320، صحیح مسلم 2714", "cats": ["sleep"]}, {"id": 157, "title": "اللہ ہی کو سہارا بنانے کی دعا", "arabic": "اللَّهُمَّ أَنْتَ عَضُدِي وَنَصِيرِي، بِكَ أَجُولُ وَبِكَ أَصُولُ وَبِكَ أُقَاتِلُ", "urdu": "اے اللہ! تو میرا بازو اور میرا مددگار ہے، تیرے ہی سہارے میں تدبیر کرتا ہوں، تیرے ہی سہارے حملہ کرتا ہوں اور تیرے ہی سہارے لڑتا ہوں۔", "ref": "سنن ابو داود 2632، سنن ترمذی 3584", "cats": ["other"]}, {"id": 158, "title": "قربانی کا جانور ذبح کرتے وقت کی دعا", "arabic": "بِسْمِ اللَّهِ، اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ", "urdu": "اللہ کے نام سے، اے اللہ! محمد ﷺ، آلِ محمد اور امتِ محمد کی طرف سے قبول فرما۔", "ref": "صحیح مسلم 1967", "cats": ["other"]}, {"id": 159, "title": "زکوٰۃ و صدقہ دینے والے کے لیے دعا", "arabic": "اللَّهُمَّ صَلِّ عَلَيْهِمْ", "urdu": "اے اللہ! ان پر رحمت نازل فرما۔", "ref": "صحیح بخاری 1497، صحیح مسلم 1078", "cats": ["other"]}, {"id": 160, "title": "قبر کو بت نہ بننے دینے کی دعا", "arabic": "اللَّهُمَّ لَا تَجْعَلْ قَبْرِي وَثَنًا يُعْبَدُ", "urdu": "اے اللہ! میری قبر کو ایسا بت نہ بنانا جس کی عبادت کی جائے۔", "ref": "مسند احمد 7352", "cats": ["other"]}, {"id": 161, "title": "ایسے ایمان کی دعا جو کبھی نہ پلٹے", "arabic": "اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ، وَنَعِيمًا لَا يَنْفَدُ، وَمُرَافَقَةَ النَّبِيِّ ﷺ فِي أَعْلَى جَنَّةِ الْخُلْدِ", "urdu": "اے اللہ! میں تجھ سے ایسا ایمان مانگتا ہوں جو پلٹ نہ جائے، ایسی نعمت جو ختم نہ ہو، اور ہمیشہ کی جنت کے سب سے اونچے درجے میں نبی ﷺ کی رفاقت۔", "ref": "مسند احمد؛ السلسلہ الصحیحہ (البانی: صحیح) — نمبر اپنی کاپی سے ملا لیں", "cats": ["other"]}, {"id": 162, "title": "رکوع میں اللہ کے سامنے مکمل خشوع کی دعا", "arabic": "اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي، وَبَصَرِي، وَمُخِّي، وَعَظْمِي، وَعَصَبِي", "urdu": "اے اللہ! میں نے تیرے ہی لیے رکوع کیا، تجھ پر ایمان لایا اور تیرا ہی فرماں بردار ہوا۔ میرے کان، میری آنکھ، میرا مغز، میری ہڈیاں اور میرے پٹھے تیرے سامنے جھک گئے۔", "ref": "صحیح مسلم 771", "cats": ["salah"]}, {"id": 163, "title": "رکوع اور سجدے کی تسبیحات", "arabic": "سُبْحَانَ رَبِّيَ الْعَظِيمِ (رکوع میں)، سُبْحَانَ رَبِّيَ الْأَعْلَى (سجدے میں)", "urdu": "میرا عظمت والا رب پاک ہے (رکوع میں)، میرا بلند و برتر رب پاک ہے (سجدے میں)۔", "ref": "صحیح مسلم 772", "cats": ["salah"]}, {"id": 164, "title": "رکوع سے اٹھنے کے بعد حمد کی وسعت والی دعا", "arabic": "رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ", "urdu": "اے ہمارے رب! تیرے ہی لیے تعریف ہے، آسمانوں کے بھر جانے کے برابر، زمین کے بھر جانے کے برابر، اور اس کے بعد جس چیز کے بھر جانے کے برابر تو چاہے۔", "ref": "صحیح مسلم 476", "cats": ["salah"]}, {"id": 165, "title": "سونے سے پہلے تسبیحِ فاطمہ", "arabic": "سُبْحَانَ اللَّهِ (33 بار)، الْحَمْدُ لِلَّهِ (33 بار)، اللَّهُ أَكْبَرُ (34 بار)", "urdu": "اللہ پاک ہے، تمام تعریف اللہ کے لیے ہے، اللہ سب سے بڑا ہے۔ (حدیث کے مطابق یہ خادم سے بہتر ہے۔)", "ref": "صحیح بخاری 3113، صحیح مسلم 2727", "cats": ["sleep"]}, {"id": 166, "title": "حکمرانوں اور ذمہ داروں کے لیے نبی ﷺ کی دعا (رحمت اور سختی کا بدلہ)", "arabic": "اللَّهُمَّ مَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَشَقَّ عَلَيْهِمْ فَاشْقُقْ عَلَيْهِ، وَمَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَرَفَقَ بِهِمْ فَارْفُقْ بِهِ", "urdu": "اے اللہ! میری امت کے کسی معاملے کا جو بھی ذمہ دار بنے اور ان پر سختی کرے تو اس پر سختی فرما، اور جو بھی ذمہ دار بنے اور ان کے ساتھ نرمی کرے تو اس کے ساتھ نرمی فرما۔", "ref": "صحیح مسلم 1828", "cats": ["other"]}, {"id": 167, "title": "کسی کو تکلیف پہنچ جائے تو اس کے حق میں رحمت بنانے کی دعا", "arabic": "اللَّهُمَّ إِنِّي أَتَّخِذُ عِنْدَكَ عَهْدًا لَنْ تُخْلِفَنِيهِ، فَإِنَّمَا أَنَا بَشَرٌ، فَأَيُّ الْمُؤْمِنِينَ آذَيْتُهُ، أَوْ شَتَمْتُهُ، أَوْ جَلَدْتُهُ، أَوْ لَعَنْتُهُ، فَاجْعَلْهَا لَهُ صَلَاةً وَزَكَاةً وَقُرْبَةً تُقَرِّبُهُ بِهَا إِلَيْكَ يَوْمَ الْقِيَامَةِ", "urdu": "اے اللہ! میں تجھ سے ایک وعدہ لیتا ہوں جس کی تو خلاف ورزی نہیں کرے گا، میں تو ایک انسان ہوں، پس جس مومن کو میں نے تکلیف دی، یا برا کہا، یا مارا، یا لعنت کی، تو اسے اس کے لیے رحمت، پاکیزگی اور ایسی قربت بنا دے جس کے ذریعے تو اسے قیامت کے دن اپنے قریب کر لے۔", "ref": "صحیح مسلم 2601", "cats": ["other"]}, {"id": 168, "title": "بقیع کے مدفون مسلمانوں کے لیے مغفرت کی دعا", "arabic": "اللَّهُمَّ اغْفِرْ لِأَهْلِ بَقِيعِ الْغَرْقَدِ", "urdu": "اے اللہ! بقیعِ غرقد (مدینہ کے قبرستان) کے رہنے والوں کو بخش دے۔", "ref": "صحیح مسلم 974", "cats": ["janaza"]}, {"id": 169, "title": "حج و عمرہ میں سر منڈوانے اور بال کتروانے والوں کے لیے دعا", "arabic": "اللَّهُمَّ ارْحَمِ الْمُحَلِّقِينَ، وَالْمُقَصِّرِينَ", "urdu": "اے اللہ! سر منڈوانے والوں پر رحم فرما، اور بال کتروانے والوں پر بھی۔", "ref": "صحیح بخاری 1727، صحیح مسلم 1301", "cats": ["other"]}, {"id": 170, "title": "کسی کے لیے ثابت قدمی اور ہدایت یافتہ رہنما بننے کی دعا", "arabic": "اللَّهُمَّ ثَبِّتْهُ، وَاجْعَلْهُ هَادِيًا مَهْدِيًّا", "urdu": "اے اللہ! اسے ثابت قدم رکھ اور اسے ہدایت دینے والا اور ہدایت یافتہ بنا دے۔", "ref": "صحیح بخاری 3036", "cats": ["other"]}, {"id": 171, "title": "یتیم اور عورت کے حقوق کی حفاظت کی دعا", "arabic": "اللَّهُمَّ إِنِّي أُحَرِّجُ حَقَّ الضَّعِيفَيْنِ: الْيَتِيمِ وَالْمَرْأَةِ", "urdu": "اے اللہ! میں دو کمزوروں، یتیم اور عورت، کے حق کو (ضائع کرنا) گناہ قرار دیتا ہوں اور اس سے خبردار کرتا ہوں۔", "ref": "سنن ابن ماجہ 3678", "cats": ["other"]}, {"id": 172, "title": "صبح کے وقت ہر نعمت پر شکر کی دعا", "arabic": "اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ", "urdu": "اے اللہ! جو نعمت آج صبح مجھے یا تیری مخلوق میں سے کسی کو ملی وہ تیری ہی طرف سے ہے، تو اکیلا ہے، تیرا کوئی شریک نہیں، پس تیرے ہی لیے تعریف ہے اور تیرے ہی لیے شکر ہے۔", "ref": "سنن ابو داود 5073", "cats": ["morning"]}], "cats": [{"id": "morning", "name": "صبح کے اذکار", "icon": "🌅", "ids": [14, 17, 25, 26, 61, 109, 110, 111, 112, 113, 120, 146, 172]}, {"id": "evening", "name": "شام کے اذکار", "icon": "🌇", "ids": [14, 25, 26, 61, 110, 111, 112, 113]}, {"id": "evil_eye", "name": "نظرِ بد سے حفاظت", "icon": "🧿", "ids": [56, 59]}, {"id": "magic_shaitan", "name": "شیاطین اور جادو سے حفاظت", "icon": "🛡️", "ids": [41, 43, 53, 58, 59, 94, 98, 111, 112, 121]}, {"id": "illness", "name": "بیماری اور شفا", "icon": "🌿", "ids": [24, 25, 54, 55, 56, 57, 59, 88, 108, 142, 143]}, {"id": "daily", "name": "روزمرہ زندگی کی دعائیں", "icon": "🏠", "ids": [18, 39, 40, 46, 49, 50, 58, 71, 75, 76, 77, 78, 79, 87, 89, 90, 91, 92, 93, 94, 95, 96, 97, 121, 122, 135, 136, 137, 138, 140, 147]}, {"id": "sleep", "name": "سونے اور جاگنے کے اذکار", "icon": "🌙", "ids": [42, 68, 69, 70, 72, 107, 156, 165]}, {"id": "salah", "name": "نماز سے متعلق اذکار", "icon": "🕌", "ids": [31, 32, 33, 34, 35, 36, 37, 38, 44, 45, 73, 99, 100, 106, 114, 115, 116, 117, 118, 123, 124, 125, 126, 127, 128, 129, 162, 163, 164]}, {"id": "distress", "name": "پریشانی، قرض اور مشکلات", "icon": "🤲", "ids": [14, 15, 19, 20, 42, 62, 63, 64, 65, 66, 80, 81, 86, 129, 132, 133, 145, 155]}, {"id": "istighfar", "name": "استغفار اور توبہ", "icon": "🕊️", "ids": [5, 35, 45, 61, 104, 105, 119, 126]}, {"id": "janaza", "name": "جنازہ، قبرستان اور تعزیت", "icon": "⚰️", "ids": [82, 83, 84, 85, 148, 149, 150, 168]}, {"id": "other", "name": "دیگر مسنون دعائیں", "icon": "📿", "ids": [1, 2, 3, 4, 6, 7, 8, 9, 10, 11, 12, 13, 16, 21, 22, 23, 27, 28, 29, 30, 47, 48, 51, 52, 60, 67, 74, 101, 102, 103, 130, 131, 134, 139, 141, 144, 151, 152, 153, 154, 157, 158, 159, 160, 161, 166, 167, 169, 170, 171]}]};